function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  // Dates start near the end of January so streaks often cross into February.
  const day = offset => new Date(Date.UTC(2023, 0, 27) + offset * 86400000).toISOString().slice(0, 10);
  const customers = size === 'small' ? 1 + pick(3) : 40;
  const counts = new Array(customers).fill(size === 'small' ? 0 : 50);
  if (size === 'small') for (let k = pick(9); k > 0; k--) counts[pick(customers)]++;
  const rows = [];
  counts.forEach((count, c) => {
    let offset = pick(4), amount = 50 + 10 * pick(10);
    for (let k = 0; k < count; k++) {
      rows.push([0, 101 + c, day(offset), amount]);
      offset += rand() < 0.75 ? 1 : 2 + pick(3);
      const r = rand();
      amount = r < 0.7 ? amount + 10 * (1 + pick(4)) : r < 0.85 ? amount : Math.max(10, amount - 10 * (1 + pick(4)));
    }
  });
  for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  rows.forEach((row, i) => { row[0] = i + 1; });
  return [{ Transactions: rows }];
}
